WITH TotalScores AS (SELECT player_id, SUM(score) AS score FROM (SELECT first_player AS player_id, first_score AS score FROM Matches UNION ALL SELECT second_player AS player_id, second_score AS score FROM Matches) s GROUP BY player_id), Ranked AS (SELECT p.group_id, p.player_id, ROW_NUMBER() OVER (PARTITION BY p.group_id ORDER BY COALESCE(t.score, 0) DESC, p.player_id ASC) AS rn FROM Players p LEFT JOIN TotalScores t ON p.player_id = t.player_id) SELECT group_id, player_id FROM Ranked WHERE rn = 1;
